mapper.select:
select a.id, a.product_seq, b.product_code, a.product_name, a.num, a.remark, a.created_by, a.created_date, a.last_upd_by, a.last_upd_date
from micro_finished_product_storage a
    left join micro_product b on a.product_seq = b.product_seq

     and a.product_seq = #{productSeq}
     and a.product_name like concat('%', #{productName}, '%')
     and a.num = #{num}
     and a.created_by = #{createdBy}
     and a.created_date = #{createdDate}
     and a.last_upd_by = #{lastUpdBy}
     and a.last_upd_date = #{lastUpdDate}

        and (b.product_code like concat('%', #{productCodeOrName}, '%')
             or b.product_name like concat('%', #{productCodeOrName}, '%'))


order by a.num desc

mapper.update:
update micro_finished_product_storage
product_seq = #{productSeq}, product_name = #{productName}, num = #{num}, remark = #{remark}, created_by = #{createdBy}, created_date = #{createdDate}, last_upd_by = #{lastUpdBy}, last_upd_date = #{lastUpdDate},
where id = #{id}

update micro_finished_product_storage
product_name = #{productName}, num = #{num}, remark = #{remark}, created_by = #{createdBy}, created_date = #{createdDate}, last_upd_by = #{lastUpdBy}, last_upd_date = #{lastUpdDate},
where product_seq = #{productSeq}
